/**
 * Street toughs and recruits, born 1930-1948: the men and women the player
 * can bring along, groom and someday hand a crew. Each has an origin, a
 * specialty, a leadership ceiling, a groomability score and a personal arc
 * (where he ends up if nobody intervenes).
 *
 * Women in the life keep books, bank numbers, fence goods and own clubs.
 * Nobody here is a victim to be exploited; the player cannot run trafficking
 * or coercion, and these characters are written as people with their own goals.
 */
import { P } from './build';
import type { Archetype } from './generators';
import type { GameFaction, Origin, RelKind, SecretKind, StreetOrigin, StreetSpecialty, TieKind, WorldPerson, WorldTrait, WorldVice } from './schema';

const OFFICE: Record<StreetSpecialty, string> = {
  boxer: 'Club fighter', wheelman: 'Driver', safecracker: 'Box man (safecracker)', 'bookie-runner': 'Bookmaker\'s runner', 'numbers-kid': 'Numbers runner',
  'card-sharp': 'Card mechanic', muscle: 'Muscle', fixer: 'Fixer', 'smooth-talker': 'Hustler', bookkeeper: 'Bookkeeper', 'numbers-banker': 'Numbers banker',
  fence: 'Fence', 'club-owner': 'Club owner', forger: 'Forger', burglar: 'Burglar', shylock: 'Shylock', mechanic: 'Mechanic', torch: 'Torch (arsonist for hire)',
};

interface Tough {
  id: string; n: string; last?: string; nick?: string; f?: boolean; b: number; o: Origin; home: StreetOrigin; sp: StreetSpecialty;
  lp: number; gr: number; rec: number; with?: GameFaction; a: Archetype; t: WorldTrait[]; v?: WorldVice[];
  pub: string; hid: string; arc: string; hook: string; cash?: number;
  rel?: [RelKind, string, string?][]; s?: [SecretKind, 1 | 2 | 3, string, string?, boolean?, string[]?][];
  debt?: [string, 'money' | 'favor' | 'loyalty', number, string?][]; ties?: [TieKind, string, number, string?][];
}

function T(x: Tough): WorldPerson {
  const w = x.with ?? 'none';
  const ties = [...(x.ties ?? [])];
  if (w !== 'none' && !ties.some((t) => t[0] === 'crime' && t[1] === w)) ties.push(['crime', w, 60, 'Runs with them now']);
  return P({
    id: x.id, n: x.n, last: x.last, nick: x.nick, f: x.f, b: x.b, o: x.o, home: x.home, inst: 'street',
    off: OFFICE[x.sp], a: x.a, t: x.t, v: x.v, pub: x.pub, hid: x.hid, hook: x.hook,
    rel: x.rel, s: x.s, debt: x.debt, ties, w: x.cash ?? (x.lp > 60 ? 1500 : 400),
    rank: w === 'none' ? 'civilian' : 'associate',
    st: [x.home, x.sp, x.lp, x.gr, x.rec, w, x.arc],
  });
}

